import{_ as p,r as n,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Pagination - October CMS - 3.x","titleTemplate":false,"description":"Learn how to display pagination links.","frontmatter":{"subtitle":"Learn how to display pagination links."},"headers":[{"level":2,"title":"Paginating Data","slug":"paginating-data","link":"#paginating-data","children":[{"level":3,"title":"Multiple Pagination Instances","slug":"multiple-pagination-instances","link":"#multiple-pagination-instances","children":[]},{"level":3,"title":"Using Custom Pagination Markup","slug":"using-custom-pagination-markup","link":"#using-custom-pagination-markup","children":[]}]},{"level":2,"title":"AJAX Pagination","slug":"ajax-pagination","link":"#ajax-pagination","children":[]},{"level":2,"title":"Load More Pagination","slug":"load-more-pagination","link":"#load-more-pagination","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/cms/features/pagination.md","filePath":"3.x/cms/features/pagination.md"}'),u={name:"3.x/cms/features/pagination.md"};function g(r,a,k,d,m,h){const t=n("pre-heading"),e=n("post-heading");return o(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Pagination",-1)),s(e),a[1]||(a[1]=i(`<p>October CMS includes pagination features out of the box, it integrates with standard templates and offers complete flexibility for custom markup. Paginated records are integrated closely with <a href="./../../extend/database/pagination.html">model pagination queries</a> and the <a href="./../../markup/function/pager.html"><code>pager()</code> Twig function</a>.</p><h2 id="paginating-data"><a href="#paginating-data" class="header-anchor">#</a> Paginating Data</h2><p>A paginated set of data can come from <a href="./../../extend/cms-components.html">Component logic</a>, inside the page or layout <a href="./../themes/themes.html">PHP section</a>, or from <a href="./../tailor/components.html">a Tailor component</a>. The following is an example of a page requesting paginated data from a Tailor component, stepping through the records at <strong>10</strong> per page.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> collection<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Now the <code>posts</code> variable is available. We can loop through each record and display the pagination links.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>nav</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>posts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>nav</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="multiple-pagination-instances"><a href="#multiple-pagination-instances" class="header-anchor">#</a> Multiple Pagination Instances</h3><p>By default the pagination will take the current page number from the <code>?page</code> query string, so the same page number will be used when displaying two or more sets of paginated data. To solve this problem, use the <code>paginateCustom</code> method and specify a unique parameter name.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection category</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Category</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginateCustom<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>postPage<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> comments <span class="token operator">=</span> comments<span class="token punctuation">.</span>paginateCustom<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>commentPage<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Set the <code>withQuery</code> option to preserve the page number for other pagination instances (optional).</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>categories<span class="token punctuation">,</span> <span class="token punctuation">{</span> withQuery<span class="token punctuation">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>This results in the query string containing both page numbers, for example,<br><code>?postPage=1&amp;commentPage=2</code>.</p><h3 id="using-custom-pagination-markup"><a href="#using-custom-pagination-markup" class="header-anchor">#</a> Using Custom Pagination Markup</h3><p>To use custom pagination markup, start with the file locations below and copy the contents to a partial inside your theme.</p><div class="table"><table tabindex="0"><thead><tr><th>Template</th><th>Detail</th></tr></thead><tbody><tr><td><code>default</code></td><td>Renders the default pagination template.<br>Location: <code>~/modules/system/views/pagination/default.htm</code></td></tr><tr><td><code>simple</code></td><td>Renders pagination with only next and previous buttons.<br>Location: <code>~/modules/system/views/pagination/simple.htm</code></td></tr><tr><td><code>ajax</code></td><td>Renders AJAX paginated records.<br>Location: <code>~/modules/system/views/pagination/ajax.htm</code></td></tr></tbody></table></div><p>Then render as a partial by passing the <code>partial</code> option to the pager.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>records<span class="token punctuation">,</span> <span class="token punctuation">{</span> partial<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-custom-pagination<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="ajax-pagination"><a href="#ajax-pagination" class="header-anchor">#</a> AJAX Pagination</h2><p>Use the <code>ajaxPager()</code> Twig function to update paginated records dynamically using AJAX. The partial should display the records and include the pager inside, for example, a partial named <strong>latest-posts.htm</strong> with the following contents.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>nav</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> ajaxPager<span class="token punctuation">(</span>posts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>nav</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Then render the partial on the page using the <a href="./../../markup/tag/ajax-partial.html"><code>{% ajaxPartial %}</code> Twig tag</a>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span>Latest Posts<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>latest-posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Alternatively, you can encapsulate all the logic inside the partial to make it completely portable.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>nav</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> ajaxPager<span class="token punctuation">(</span>posts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>nav</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>The partial can then be rendered anywhere on a page or layout without any additional configuration.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>latest-posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h2 id="load-more-pagination"><a href="#load-more-pagination" class="header-anchor">#</a> Load More Pagination</h2><p>A load more button, sometimes called an infinite loader, is a method of displaying records in a stack instead of across multiple pages.</p><p>This approach uses an AJAX partial to append the new content along with a self-destructing button. For example, a partial named <strong>load-more-posts.htm</strong> with the following contents.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> posts<span class="token punctuation">.</span>hasMorePages <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: &#39;@&#39; }<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-success</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>this.remove()<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ page: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> posts<span class="token punctuation">.</span>currentPage <span class="token operator">+</span> <span class="token number">1</span> <span class="token delimiter punctuation">}}</span></span> }<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Load More
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The button element leverages a combination of AJAX data attributes to perform <a href="./../ajax/update-partials.html">a self-update in append mode</a>, passing the next page number as data and removing itself upon completion.</p><p>The partial should be rendered using <a href="./../../markup/tag/ajax-partial.html"><code>{% ajaxPartial %}</code> Twig tag</a>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>load-more-posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../extend/database/pagination.html">Model Pagination</a></li><li><a href="./../../markup/function/pager.html">Pager Twig function</a></li></ul></div>`,35))])}const f=p(u,[["render",g]]);export{v as __pageData,f as default};
